using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using Microsoft.Win32;

namespace SharkInstaller
{
    public class InstallerForm : Form
    {
        private int progress = 0;
        private System.Windows.Forms.Timer timer;
        private Label lblStage;
        private Label lblPercent;
        private Panel pnlProgress;
        private CheckBox chkLaunch;
        private Button btnFinish;
        private Image logoImg;
        private string targetDir;
        private string targetExe;
        private string targetIco;

        public InstallerForm()
        {
            this.Text = "Shark Traders AI // مثبت النظام المؤسسي v2.6";
            this.Width = 520;
            this.Height = 460;
            this.StartPosition = FormStartPosition.CenterScreen;
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = true;
            this.BackColor = Color.FromArgb(7, 9, 14);
            this.DoubleBuffered = true;

            targetDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SharkTradersAI");
            targetExe = Path.Combine(targetDir, "SharkTradersAI.exe");
            targetIco = Path.Combine(targetDir, "icon.ico");

            try
            {
                byte[] icoBytes = Convert.FromBase64String("");
                using (MemoryStream ms = new MemoryStream(icoBytes))
                {
                    this.Icon = new Icon(ms);
                }
            }
            catch { }

            try
            {
                byte[] logoBytes = Convert.FromBase64String("");
                using (MemoryStream ms = new MemoryStream(logoBytes))
                {
                    logoImg = Image.FromStream(ms);
                }
            }
            catch { }

            BuildUI();

            timer = new System.Windows.Forms.Timer();
            timer.Interval = 42; // ~4.5 seconds for 100 steps
            timer.Tick += Timer_Tick;
            this.Shown += (s, e) => timer.Start();
        }

        private void BuildUI()
        {
            // Progress Track
            pnlProgress = new Panel();
            pnlProgress.Location = new Point(36, 260);
            pnlProgress.Size = new Size(432, 16);
            pnlProgress.BackColor = Color.FromArgb(17, 24, 38);
            pnlProgress.Paint += PnlProgress_Paint;
            this.Controls.Add(pnlProgress);

            lblStage = new Label();
            lblStage.Location = new Point(36, 232);
            lblStage.Size = new Size(350, 22);
            lblStage.ForeColor = Color.FromArgb(0, 229, 255);
            lblStage.Font = new Font("Segoe UI", 9.5f, FontStyle.Bold);
            lblStage.Text = "🔍 جارٍ فحص بيئة تشغيل Windows والمحرك السحابي...";
            this.Controls.Add(lblStage);

            lblPercent = new Label();
            lblPercent.Location = new Point(390, 232);
            lblPercent.Size = new Size(78, 22);
            lblPercent.ForeColor = Color.FromArgb(255, 230, 0);
            lblPercent.Font = new Font("Segoe UI", 9.5f, FontStyle.Bold);
            lblPercent.TextAlign = ContentAlignment.TopRight;
            lblPercent.Text = "0%";
            this.Controls.Add(lblPercent);

            chkLaunch = new CheckBox();
            chkLaunch.Location = new Point(36, 300);
            chkLaunch.Size = new Size(300, 26);
            chkLaunch.ForeColor = Color.White;
            chkLaunch.Font = new Font("Segoe UI", 9.5f);
            chkLaunch.Text = "تشغيل Shark Traders AI فور انتهاء التثبيت";
            chkLaunch.Checked = true;
            chkLaunch.Visible = false;
            this.Controls.Add(chkLaunch);

            btnFinish = new Button();
            btnFinish.Location = new Point(36, 345);
            btnFinish.Size = new Size(432, 46);
            btnFinish.BackColor = Color.FromArgb(0, 229, 255);
            btnFinish.ForeColor = Color.FromArgb(7, 9, 14);
            btnFinish.Font = new Font("Segoe UI", 11.5f, FontStyle.Bold);
            btnFinish.FlatStyle = FlatStyle.Flat;
            btnFinish.FlatAppearance.BorderSize = 0;
            btnFinish.Text = "🚀 إنهاء وتشغيل البرنامج الآن";
            btnFinish.Cursor = Cursors.Hand;
            btnFinish.Visible = false;
            btnFinish.Click += (s, e) =>
            {
                if (chkLaunch.Checked && File.Exists(targetExe))
                {
                    try { Process.Start(targetExe); } catch { }
                }
                Application.Exit();
            };
            this.Controls.Add(btnFinish);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            // Draw header background
            using (SolidBrush hdrBrush = new SolidBrush(Color.FromArgb(12, 17, 28)))
            {
                g.FillRectangle(hdrBrush, 0, 0, this.Width, 190);
            }
            using (Pen borderPen = new Pen(Color.FromArgb(0, 229, 255), 1.5f))
            {
                g.DrawLine(borderPen, 0, 190, this.Width, 190);
            }

            // Draw Logo
            if (logoImg != null)
            {
                g.DrawImage(logoImg, new Rectangle(36, 26, 80, 80));
            }

            // Draw Titles
            using (Font titleFont = new Font("Segoe UI", 15.5f, FontStyle.Bold))
            using (SolidBrush goldBrush = new SolidBrush(Color.FromArgb(255, 230, 0)))
            {
                g.DrawString("SHARK TRADERS AI", titleFont, goldBrush, 130, 28);
            }

            using (Font subFont = new Font("Segoe UI", 9.5f))
            using (SolidBrush textBrush = new SolidBrush(Color.FromArgb(200, 215, 235)))
            {
                g.DrawString("المثبت المؤسسي لنظام ويندوز • v2.6", subFont, new SolidBrush(Color.FromArgb(0, 229, 255)), 130, 58);
                g.DrawString("تثبيت منصة التداول الذكية بدقة 256x256 مع الربط المباشر", subFont, textBrush, 130, 80);
                g.DrawString("بمتصفح Google Chrome والمحرك السحابي Supabase", subFont, textBrush, 130, 100);
            }
        }

        private void PnlProgress_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            int fillWidth = (int)((pnlProgress.Width * progress) / 100.0);
            if (fillWidth > 0)
            {
                using (LinearGradientBrush brush = new LinearGradientBrush(
                    new Rectangle(0, 0, fillWidth, pnlProgress.Height),
                    Color.FromArgb(0, 229, 255),
                    progress >= 100 ? Color.FromArgb(0, 255, 102) : Color.FromArgb(255, 230, 0),
                    LinearGradientMode.Horizontal))
                {
                    g.FillRectangle(brush, 0, 0, fillWidth, pnlProgress.Height);
                }
            }
        }

        private void Timer_Tick(object sender, EventArgs e)
        {
            progress++;
            if (progress > 100) progress = 100;

            lblPercent.Text = progress + "%";

            if (progress == 20)
            {
                lblStage.Text = "⚡ تجهيز محرك الذكاء الاصطناعي وبطاقة الرسوميات...";
            }
            else if (progress == 45)
            {
                lblStage.Text = "📦 استخراج ملفات Shark Traders AI وتثبيتها...";
                PerformFileExtraction();
            }
            else if (progress == 70)
            {
                lblStage.Text = "🌐 ضبط الربط السلس مع متصفح Google Chrome والمكتبات...";
            }
            else if (progress == 88)
            {
                lblStage.Text = "🖥️ إنشاء اختصار سطح المكتب بدقة 256x256 وتسجيل النظام...";
                CreateShortcutsAndRegistry();
            }
            else if (progress >= 100)
            {
                timer.Stop();
                lblStage.ForeColor = Color.FromArgb(0, 255, 102);
                lblStage.Text = "✅ اكتمل التثبيت بنجاح تام (100%)! جاهز للتشغيل.";
                chkLaunch.Visible = true;
                btnFinish.Visible = true;
            }

            pnlProgress.Invalidate();
        }

        private void PerformFileExtraction()
        {
            try
            {
                if (!Directory.Exists(targetDir)) Directory.CreateDirectory(targetDir);

                // Write Exe
                byte[] exeBytes = Convert.FromBase64String("");
                File.WriteAllBytes(targetExe, exeBytes);

                // Write WebView2 DLLs
                File.WriteAllBytes(Path.Combine(targetDir, "Microsoft.Web.WebView2.WinForms.dll"), Convert.FromBase64String(""));
                File.WriteAllBytes(Path.Combine(targetDir, "Microsoft.Web.WebView2.Core.dll"), Convert.FromBase64String(""));
                File.WriteAllBytes(Path.Combine(targetDir, "WebView2Loader.dll"), Convert.FromBase64String(""));

                // Write Icon
                File.WriteAllBytes(targetIco, Convert.FromBase64String(""));
            }
            catch (Exception ex)
            {
                MessageBox.Show("Extraction warning: " + ex.Message);
            }
        }

        private void CreateShortcutsAndRegistry()
        {
            try
            {
                // Register sharktraders:// protocol
                using (var key = Registry.CurrentUser.CreateSubKey(@"SoftwareClasses\sharktraders"))
                {
                    key.SetValue("", "URL:SharkTradersAI Protocol");
                    key.SetValue("URL Protocol", "");
                    using (var cmdKey = key.CreateSubKey(@"shell\open\command"))
                    {
                        cmdKey.SetValue("", "\"" + targetExe + "\" \"%1\"");
                    }
                }

                // Create Desktop Shortcut via WScript.Shell
                string desktopPath = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
                string shortcutPath = Path.Combine(desktopPath, "Shark Traders AI.lnk");

                Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                dynamic shell = Activator.CreateInstance(shellType);
                dynamic shortcut = shell.CreateShortcut(shortcutPath);
                shortcut.TargetPath = targetExe;
                shortcut.WorkingDirectory = targetDir;
                shortcut.Description = "Shark Traders AI - Institutional Quant Platform";
                shortcut.IconLocation = targetExe + ",0";
                shortcut.Save();

                // Create Start Menu Shortcut
                string startMenu = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs");
                string startShortcut = Path.Combine(startMenu, "Shark Traders AI.lnk");
                dynamic sc2 = shell.CreateShortcut(startShortcut);
                sc2.TargetPath = targetExe;
                sc2.WorkingDirectory = targetDir;
                sc2.IconLocation = targetExe + ",0";
                sc2.Save();
            }
            catch { }
        }

        [STAThread]
        static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new InstallerForm());
        }
    }
}
